<script>
import { onMount } from 'svelte';
export let data;
const SUPABASE_URL='https://uawddygirnbpmkjhqcvu.supabase.co';
const KEY='sb_publishable_bEps0rM2t0HJsA6BPLjQPg_becZ1PsM';
const POS=['QB','RB','WR','TE','K','DEF'];
let mode='home',name='',room=null,teams=[],picks=[],activeRooms=[],loading=false,error='';
let pollTimer,timerTick,clientToken='',search='',positionFilter='ALL',cpuWorking=false,secondsLeft=60,lastPickSeen=null,shareNotice='';
let sideTab='players',chatMessages=[],chatText='',chatReady=true,chatError='';
const players=Object.entries(data?.playerData?.players||{}).map(([id,p])=>({id,...p})).filter(p=>POS.includes(pos(p))&&(p.fn||p.first_name||p.ln||p.last_name));
function pos(p){const x=p.pos||p.position;return x==='DST'?'DEF':x||'UNK'}
function pname(p){const f=p.fn||p.first_name||'',l=p.ln||p.last_name||'';return pos(p)==='DEF'?(p.t||p.team||`${f} ${l}`.trim()):(`${f} ${l}`.trim()||p.full_name||'Unknown Player')}
function rank(p){const n=Number(p.search_rank??p.rank??9999);return Number.isFinite(n)&&n>0?n:9999}
function isAutoTeam(t){return !!t?.is_cpu&&!!t?.player_token} function isOpenCpu(t){return !!t?.is_cpu&&!t?.player_token}
function hdr(prefer){return{apikey:KEY,Authorization:`Bearer ${KEY}`,'Content-Type':'application/json',...(prefer?{Prefer:prefer}:{})}}
async function req(path,o={}){const r=await fetch(`${SUPABASE_URL}/rest/v1/${path}`,{...o,headers:{...hdr(o.prefer),...(o.headers||{})}});if(!r.ok)throw new Error(await r.text()||`Request failed ${r.status}`);const t=await r.text();return t?JSON.parse(t):null}
function snakeSlot(n,c=10){const r=Math.floor((n-1)/c)+1,p=(n-1)%c+1;return r%2?p:c-p+1} function overallFor(r,s,c=10){const p=r%2?s:c-s+1;return(r-1)*c+p}
function ctx(n=Number(room?.current_pick||1)){const c=Number(room?.team_count||10),round=Math.floor((n-1)/c)+1,pickInRound=(n-1)%c+1,slot=snakeSlot(n,c);return{overallPick:n,round,pickInRound,slot,team:teams.find(t=>Number(t.draft_slot)===slot)}}
$: current=room?ctx():null;
$: myTeam=teams.find(t=>t.player_token===clientToken)||null;
$: myTurn=room?.status==='drafting'&&current?.team?.player_token===clientToken&&!current?.team?.is_cpu;
$: drafted=new Set(picks.map(p=>String(p.player_id)));
$: myPicks=myTeam?picks.filter(p=>p.team_id===myTeam.id).sort((a,b)=>a.overall_pick-b.overall_pick):[];
$: available=players.filter(p=>!drafted.has(String(p.id))).filter(p=>positionFilter==='ALL'||pos(p)===positionFilter).filter(p=>{const q=search.trim().toLowerCase();return!q||pname(p).toLowerCase().includes(q)||(p.t||p.team||'').toLowerCase().includes(q)}).sort((a,b)=>rank(a)-rank(b)).slice(0,120);
async function loadActive(){try{activeRooms=await req('mock_rooms?status=in.(lobby,drafting)&select=*&order=created_at.desc&limit=8')||[]}catch(e){console.error(e)}}
async function refreshChat(){if(!room?.id||sideTab!=='chat')return;try{chatMessages=await req(`mock_chat?room_id=eq.${room.id}&select=*&order=created_at.asc&limit=80`)||[];chatReady=true;chatError=''}catch(e){chatReady=false;chatError='Chat needs the Supabase mock_chat table setup.'}}
async function refresh(){if(!room?.id)return;try{const[rr,tt,pp]=await Promise.all([req(`mock_rooms?id=eq.${room.id}&select=*`),req(`mock_teams?room_id=eq.${room.id}&select=*&order=draft_slot.asc`),req(`mock_picks?room_id=eq.${room.id}&select=*&order=overall_pick.asc`)]);if(!rr?.length){leaveLocal();return}room=rr[0];teams=tt||[];picks=pp||[];mode=['drafting','completed'].includes(room.status)?'draft':'room';if(sideTab==='chat')refreshChat();if(room.status==='drafting')requestAnimationFrame(maybeCpu)}catch(e){console.error(e)}}
function polling(){clearInterval(pollTimer);pollTimer=setInterval(refresh,1500)}
async function createRoom(){error='';loading=true;try{const made=await req('mock_rooms',{method:'POST',prefer:'return=representation',body:JSON.stringify({room_code:crypto.randomUUID().replace(/-/g,'').slice(0,12).toUpperCase(),host_id:clientToken,team_count:10,rounds:16,status:'lobby',current_pick:1})});room=made?.[0];if(!room)throw Error('Room could not be created.');await req('mock_teams',{method:'POST',prefer:'return=minimal',body:JSON.stringify(Array.from({length:10},(_,i)=>({room_id:room.id,draft_slot:i+1,is_cpu:true})))});await refresh();polling()}catch(e){error=e.message}finally{loading=false}}
async function join(r){room=r;await refresh();polling()}
async function claim(t){if(!name.trim()){error='Enter your name before claiming a team.';return}const mine=teams.find(x=>x.player_token===clientToken);if(mine&&mine.id!==t.id)await req(`mock_teams?id=eq.${mine.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({manager_name:null,player_token:null,is_cpu:true})});await req(`mock_teams?id=eq.${t.id}&is_cpu=eq.true&player_token=is.null`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({manager_name:name.trim(),player_token:clientToken,is_cpu:false})});await refresh()}
async function release(t){await req(`mock_teams?id=eq.${t.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({manager_name:null,player_token:null,is_cpu:true})});await refresh()}
async function resumeManual(t){if(t?.player_token!==clientToken||!isAutoTeam(t))return;await req(`mock_teams?id=eq.${t.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({is_cpu:false})});await refresh()}
async function startDraft(){if(room?.host_id!==clientToken){error='Only the host can start the draft.';return}if(!teams.some(t=>t.player_token===clientToken)){error='Claim a slot before starting.';return}await req(`mock_rooms?id=eq.${room.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({status:'drafting',current_pick:1})});await refresh()}
function counts(id){const c={QB:0,RB:0,WR:0,TE:0,K:0,DEF:0};picks.filter(p=>p.team_id===id).forEach(p=>{if(c[p.position]!=null)c[p.position]++});return c}
function cpuScore(p,id,r){const c=counts(id),z=pos(p);let x=10000-rank(p)*10;if(z==='QB'){if(c.QB===0&&r>=3)x+=70;if(c.QB===1&&r>=5)x+=50;if(c.QB>=2)x-=220;if(c.QB>=3)x-=1200}if(z==='RB'){if(c.RB<2)x+=55;if(c.RB>=5)x-=180}if(z==='WR'){if(c.WR<2)x+=45;if(c.WR>=6)x-=180}if(z==='TE'){if(c.TE===0&&r>=4)x+=35;if(c.TE>=2)x-=180}if(z==='K'||z==='DEF'){if(r<13)x-=1500;if(c[z]>=1)x-=3000}return x}
function bestCpu(team,round){const pool=players.filter(p=>!drafted.has(String(p.id))).sort((a,b)=>cpuScore(b,team.id,round)-cpuScore(a,team.id,round));return pool[0]}
async function makePick(p,team=current?.team){if(!room||!team||room.status!=='drafting')return;const c=ctx(Number(room.current_pick));if(c.team?.id!==team.id)return;try{await req('mock_picks',{method:'POST',prefer:'return=minimal',body:JSON.stringify({room_id:room.id,team_id:team.id,overall_pick:c.overallPick,round:c.round,pick_in_round:c.pickInRound,player_id:String(p.id),player_name:pname(p),position:pos(p)})});const total=Number(room.team_count||10)*Number(room.rounds||16);await req(`mock_rooms?id=eq.${room.id}&current_pick=eq.${c.overallPick}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({current_pick:Math.min(c.overallPick+1,total+1),status:c.overallPick>=total?'completed':'drafting'})});await refresh()}catch(e){await refresh()}}
async function draftPlayer(p){if(myTurn)await makePick(p,current.team)} async function maybeCpu(){if(cpuWorking||room?.status!=='drafting')return;const c=ctx();if(!c.team?.is_cpu)return;cpuWorking=true;try{const p=bestCpu(c.team,c.round);if(p){await new Promise(r=>setTimeout(r,700));await makePick(p,c.team)}}finally{cpuWorking=false}}
async function autoHuman(){if(room?.status!=='drafting'||secondsLeft>0||cpuWorking)return;const c=ctx();if(!c.team||c.team.is_cpu)return;cpuWorking=true;try{await req(`mock_teams?id=eq.${c.team.id}&is_cpu=eq.false`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({is_cpu:true})});const p=bestCpu(c.team,c.round);if(p)await makePick(p,c.team)}finally{cpuWorking=false}}
async function sendChat(){const text=chatText.trim();if(!text||!room?.id||!myTeam)return;chatText='';try{await req('mock_chat',{method:'POST',prefer:'return=minimal',body:JSON.stringify({room_id:room.id,player_token:clientToken,manager_name:myTeam.manager_name||name||'Manager',message:text})});await refreshChat()}catch(e){chatText=text;chatReady=false;chatError='Chat needs the Supabase mock_chat table setup.'}}
function changeSideTab(tab){sideTab=tab;if(tab==='chat')refreshChat()}
async function finishDraft(){if(room?.host_id!==clientToken)return;if(!confirm('Finish this mock now? The draft will become read-only.'))return;await req(`mock_rooms?id=eq.${room.id}`,{method:'PATCH',prefer:'return=minimal',body:JSON.stringify({status:'completed'})});await refresh()}
async function deleteDraft(){if(room?.host_id!==clientToken)return;if(!confirm('Delete this mock draft permanently?'))return;try{await req(`mock_chat?room_id=eq.${room.id}`,{method:'DELETE',prefer:'return=minimal'}).catch(()=>{});await req(`mock_picks?room_id=eq.${room.id}`,{method:'DELETE',prefer:'return=minimal'});await req(`mock_teams?room_id=eq.${room.id}`,{method:'DELETE',prefer:'return=minimal'});await req(`mock_rooms?id=eq.${room.id}`,{method:'DELETE',prefer:'return=minimal'});leaveLocal();await loadActive()}catch(e){error='Could not delete this mock. Check Supabase delete policies.'}}
function shareUrl(){if(!room?.id||typeof window==='undefined')return'';const u=new URL(window.location.href);u.search='';u.hash='';u.searchParams.set('mock',room.id);return u.toString()}
async function shareMock(){const url=shareUrl();if(!url)return;try{if(navigator.share){await navigator.share({title:'Join my GGL Mock Draft',text:'Join this GGL fantasy football mock draft.',url});shareNotice='Shared'}else if(navigator.clipboard){await navigator.clipboard.writeText(url);shareNotice='Link copied'}else{prompt('Copy this mock draft link:',url);shareNotice='Link ready'}}catch(e){if(e?.name!=='AbortError')error='Could not share the mock link.'}if(shareNotice)setTimeout(()=>shareNotice='',1800)}
function leaveLocal(){clearInterval(pollTimer);room=null;teams=[];picks=[];chatMessages=[];mode='home';error='';shareNotice='';sideTab='players';if(typeof window!=='undefined')history.replaceState({},'',window.location.pathname)} async function leave(){leaveLocal();await loadActive()}
onMount(async()=>{clientToken=localStorage.getItem('ggl_mock_token')||crypto.randomUUID();localStorage.setItem('ggl_mock_token',clientToken);const mockId=new URLSearchParams(window.location.search).get('mock');if(mockId){try{const rows=await req(`mock_rooms?id=eq.${encodeURIComponent(mockId)}&select=*`);if(rows?.[0]){room=rows[0];await refresh();polling()}else{error='That mock draft is no longer available.';await loadActive()}}catch(e){error='Could not open that shared mock draft.';await loadActive()}}else await loadActive();timerTick=setInterval(()=>{if(room?.status!=='drafting'){secondsLeft=60;lastPickSeen=null;return}const n=Number(room.current_pick);if(lastPickSeen!==n){lastPickSeen=n;secondsLeft=60}else if(current?.team?.is_cpu){secondsLeft=60}else if(secondsLeft>0)secondsLeft--;if(secondsLeft<=0)autoHuman()},1000);return()=>{clearInterval(pollTimer);clearInterval(timerTick)}});
</script>
<svelte:head><title>GGL Mock Draft</title></svelte:head>
<div class="page"><header><small>GGL DRAFT LAB</small><h1>🎯 Mock Draft</h1><p>10-team Superflex · 16-round snake · multiplayer</p></header>
{#if mode==='home'}<section class="card home"><label>Your name<input bind:value={name} placeholder="Ricardo"></label><button class="primary" onclick={createRoom}>Start New Mock</button><h3>Active Mocks</h3>{#each activeRooms as r}<button class="active" onclick={()=>join(r)}><b>{r.status==='drafting'?'Draft in progress':'Lobby open'}</b><span>Join →</span></button>{:else}<p class="muted">No active mocks.</p>{/each}</section>
{:else if mode==='room'}<div class="top"><b>Active Lobby</b><div><button onclick={shareMock}>↗ Share Mock</button><button onclick={leave}>Leave</button></div></div>{#if shareNotice}<div>{shareNotice}</div>{/if}<section class="card"><label>Your display name<input bind:value={name}></label></section><h2>Draft Order <small>{teams.filter(t=>!isOpenCpu(t)).length}/10 joined</small></h2><div class="teams">{#each teams as t}<div class:mine={t.player_token===clientToken} class="team"><b>{t.draft_slot}. {isOpenCpu(t)?'GGL CPU':t.manager_name}{isAutoTeam(t)?' · AUTO':''}</b>{#if t.player_token===clientToken}{#if isAutoTeam(t)}<button onclick={()=>resumeManual(t)}>Resume Manual</button>{:else}<button onclick={()=>release(t)}>Release</button>{/if}{:else if isOpenCpu(t)}<button onclick={()=>claim(t)}>Claim</button>{:else}<span>{isAutoTeam(t)?'Auto Draft':'Taken'}</span>{/if}</div>{/each}</div>{#if room.host_id===clientToken}<div class="host"><button class="primary" onclick={startDraft}>Start Draft</button><button onclick={shareMock}>↗ Share Mock</button><button class="danger" onclick={deleteDraft}>Delete Mock</button></div>{:else}<p class="muted">Waiting for the host to start.</p>{/if}
{:else if mode==='draft'}<div class="top"><button onclick={leave}>← Leave</button><div><small>{room.status==='completed'?'Draft complete':`Round ${current?.round} · Pick ${current?.overallPick} · Slot ${current?.slot}`}</small><b>{room.status==='completed'?'GGL Mock Complete':`${isOpenCpu(current?.team)?'GGL CPU':current?.team?.manager_name||'Team'}${isAutoTeam(current?.team)?' (AUTO)':''} is on the clock`}</b></div><div class:turn={myTurn} class="clock">{room.status==='completed'?'FINAL':current?.team?.is_cpu?'AUTO':`${secondsLeft}s`}</div></div><div class="hostbar"><button onclick={shareMock}>↗ Share Mock</button>{#if teams.find(t=>t.player_token===clientToken&&isAutoTeam(t))}<button onclick={()=>resumeManual(teams.find(t=>t.player_token===clientToken))}>Resume Manual</button>{/if}{#if room.host_id===clientToken}<button onclick={finishDraft} disabled={room.status==='completed'}>Finish Draft</button><button class="danger" onclick={deleteDraft}>Delete Mock</button>{/if}</div><div class="layout"><section class="panel"><h2>Draft Board <small>Snake · {picks.length}/{Number(room.team_count||10)*Number(room.rounds||16)}</small></h2><div class="scroll"><div class="board"><div class="head">Rd</div>{#each teams as t}<div class="head">S{t.draft_slot}<small>{isOpenCpu(t)?'CPU':t.manager_name}{isAutoTeam(t)?' · AUTO':''}</small></div>{/each}{#each Array.from({length:Number(room.rounds||16)},(_,i)=>i+1) as r}<div class="head">R{r}</div>{#each teams as t}{@const o=overallFor(r,Number(t.draft_slot),Number(room.team_count||10))}{@const pk=picks.find(x=>x.overall_pick===o)}<div class:now={room.current_pick===o&&room.status==='drafting'} class:mine={t.player_token===clientToken} class={`pick ${pk?`p-${pk.position}`:''}`}><small>#{o}</small><b>{pk?pk.player_name:(isOpenCpu(t)?'CPU':t.manager_name)}</b><span>{pk?.position||'—'}</span></div>{/each}{/each}</div></div></section><section class="panel sidepanel"><div class="sideTabs"><button class:on={sideTab==='players'} onclick={()=>changeSideTab('players')}>Players</button><button class:on={sideTab==='team'} onclick={()=>changeSideTab('team')}>My Team <small>{myPicks.length}</small></button><button class:on={sideTab==='chat'} onclick={()=>changeSideTab('chat')}>Chat</button></div>{#if sideTab==='players'}<div class="tabTitle"><b>Available Players</b><small>{myTurn?'Make your pick':'Best available'}</small></div><input bind:value={search} placeholder="Search player or team"><div class="filters">{#each ['ALL',...POS] as p}<button class:on={positionFilter===p} onclick={()=>positionFilter=p}>{p}</button>{/each}</div><div class="list">{#each available as p}<button class={`player p-${pos(p)}`} onclick={()=>draftPlayer(p)} disabled={!myTurn||room.status!=='drafting'}><span>{rank(p)<9999?rank(p):'—'}</span><b>{pname(p)}<small>{pos(p)} · {p.t||p.team||'FA'}</small></b><strong>{myTurn?'Draft':pos(p)}</strong></button>{/each}</div><p class="muted">Human picks have 60 seconds. A timeout switches that team to Auto Draft until Resume Manual is tapped.</p>{:else if sideTab==='team'}<div class="tabTitle"><b>{myTeam?.manager_name||'My Team'}</b><small>{myPicks.length}/16 drafted</small></div>{#if myTeam}<div class="rosterSummary">{#each POS as z}<span class={`p-${z}`}>{z} {myPicks.filter(p=>p.position===z).length}</span>{/each}</div><div class="teamList">{#each myPicks as pk}<div class={`teamPick p-${pk.position}`}><span>#{pk.overall_pick}</span><b>{pk.player_name}<small>Round {pk.round} · {pk.position}</small></b></div>{:else}<p class="emptyState">Your drafted players will fill in here as the mock progresses.</p>{/each}</div>{:else}<p class="emptyState">Claim a draft slot to build your team.</p>{/if}{:else}<div class="tabTitle"><b>Draft Chat</b><small>{chatMessages.length} messages</small></div>{#if !chatReady}<p class="chatSetup">{chatError}</p>{/if}<div class="chatList">{#each chatMessages as m}<div class:mineChat={m.player_token===clientToken} class="chatMsg"><b>{m.manager_name}</b><span>{m.message}</span><small>{new Date(m.created_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</small></div>{:else}<p class="emptyState">No messages yet. Start the draft-room chat.</p>{/each}</div><div class="chatComposer"><input bind:value={chatText} onkeydown={(e)=>e.key==='Enter'&&sendChat()} placeholder="Message the draft room" disabled={!myTeam||!chatReady}><button onclick={sendChat} disabled={!chatText.trim()||!myTeam||!chatReady}>Send</button></div>{/if}</section></div>{/if}{#if error}<div class="error">{error}</div>{/if}</div>
<style>
.page{width:96%;max-width:1200px;margin:auto;padding:22px 0 70px}header{text-align:center;margin-bottom:18px}header small{font-weight:900;letter-spacing:.14em;opacity:.5}header h1{margin:5px 0}header p{margin:0;opacity:.6}.card,.top,.panel,.team{background:var(--fff);border:1px solid var(--ccc);border-radius:14px}.home{max-width:600px;margin:auto;padding:16px}label{display:flex;flex-direction:column;gap:6px;font-size:.72rem;font-weight:800}input{background:var(--f3f3f3);color:inherit;border:1px solid var(--ccc);border-radius:10px;padding:11px;font:inherit}.primary,button{cursor:pointer;font:inherit}.primary{background:var(--blueOne);color:#fff;border:0;border-radius:10px;padding:11px 14px;font-weight:900}.home>.primary{width:100%;margin-top:10px}.active{width:100%;display:flex;justify-content:space-between;padding:11px;margin:6px 0;border:1px solid var(--ccc);border-radius:10px;background:var(--f3f3f3);color:inherit}.top{position:sticky;top:0;z-index:4;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px;margin-bottom:10px}.top>div{display:flex;gap:8px}.top button,.hostbar button,.team button{border:1px solid var(--ccc);background:var(--f3f3f3);color:inherit;border-radius:9px;padding:7px 10px}.clock{font-weight:900;background:var(--f3f3f3);border-radius:999px;padding:8px 12px}.clock.turn{background:var(--blueOne);color:#fff}.teams{display:grid;grid-template-columns:1fr 1fr;gap:7px}.team{display:flex;justify-content:space-between;align-items:center;padding:10px}.mine{box-shadow:inset 0 0 0 2px var(--blueOne)}h2{font-size:1rem}h2 small{font-size:.65rem;opacity:.55}.host{display:grid;grid-template-columns:1fr auto auto;gap:8px;margin-top:12px}.danger{border:1px solid #d55!important;background:transparent!important;color:#d55!important;border-radius:10px;padding:10px;font-weight:850}.hostbar{display:flex;justify-content:flex-end;gap:8px;margin-bottom:10px}.layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:10px}.panel{overflow:hidden}.panel>h2{display:flex;justify-content:space-between;padding:11px;margin:0;border-bottom:1px solid var(--ccc)}.scroll{overflow:auto;max-height:70vh}.board{display:grid;grid-template-columns:42px repeat(10,minmax(105px,1fr));min-width:1100px}.head,.pick{border-right:1px solid var(--ccc);border-bottom:1px solid var(--ccc);padding:6px}.head{background:var(--f3f3f3);font-size:.65rem;font-weight:900}.head small{display:block;opacity:.5}.pick{min-height:55px;display:flex;flex-direction:column;justify-content:center;border-left:3px solid var(--pc,var(--ccc))}.pick small{font-size:.55rem;opacity:.45}.pick b{font-size:.7rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pick span{font-size:.58rem}.pick.now{outline:3px solid var(--blueOne);outline-offset:-3px}.sidepanel{display:flex;flex-direction:column;min-height:520px}.sideTabs{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid var(--ccc);background:var(--f3f3f3)}.sideTabs button{border:0;border-right:1px solid var(--ccc);background:transparent;color:inherit;padding:9px 6px;font-weight:850;font-size:.72rem}.sideTabs button:last-child{border-right:0}.sideTabs button.on{background:var(--fff);box-shadow:inset 0 -3px 0 var(--blueOne)}.sideTabs small{font-size:.55rem;opacity:.55}.tabTitle{display:flex;justify-content:space-between;align-items:center;padding:10px;border-bottom:1px solid var(--ccc)}.tabTitle small{font-size:.62rem;opacity:.55}.sidepanel>input{width:calc(100% - 20px);margin:10px;box-sizing:border-box}.filters{display:flex;gap:5px;overflow:auto;padding:0 10px 9px}.filters button{border:1px solid var(--ccc);background:var(--f3f3f3);color:inherit;border-radius:999px;padding:5px 8px}.filters .on{background:var(--blueOne);color:#fff}.list{max-height:48vh;overflow:auto;padding:0 8px}.player{width:100%;display:grid;grid-template-columns:30px 1fr auto;gap:7px;align-items:center;text-align:left;background:var(--fff);color:inherit;border:1px solid var(--ccc);borde